-- Editable words, prices, and Service-media filenames.
-- The public site can read these rows. Writes stay in the Supabase dashboard.

create table if not exists public.site_copy (
  key text primary key,
  value text not null,
  updated_at timestamptz not null default now()
);

comment on table public.site_copy is
  'Public site wording and Service-media filenames. Edit value in the Table Editor.';

alter table public.site_copy enable row level security;

grant select on table public.site_copy to anon, authenticated;
revoke insert, update, delete on table public.site_copy from anon, authenticated;

drop policy if exists site_copy_read on public.site_copy;
create policy site_copy_read
  on public.site_copy
  for select
  to anon, authenticated
  using (true);

create or replace function public.touch_site_copy()
returns trigger
language plpgsql
as $$
begin
  new.updated_at = now();
  return new;
end;
$$;

drop trigger if exists site_copy_updated on public.site_copy;
create trigger site_copy_updated
  before update on public.site_copy
  for each row
  execute function public.touch_site_copy();

on conflict (key) do nothing;
